// на экране «סקירת הטיוטה» остаётся только уведомление об успехе. Кейс DRAFT-001.
// Сбой генерации — подменой ответа generate-scenario-draft (422 draft_rejected), настоящая генерация AI
// не вызывается. Каждый прогон создаёт свою симуляцию «QA-AUTO-DRAFT-…» в статусе טיוטה (@data).
// Удалять её тест не будет: правило проекта — тестовые данные удаляются только с «да» пользователя.
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';

const FAIL_TITLE = 'הפקת הטיוטה נכשלה';
const SAVED_TITLE = 'הטיוטה נשמרה';

/** Ответ функции генерации подменяется на 422 draft_rejected (как при проверке тикета). */
async function failGeneration(page: Page) {
  await page.route('**/functions/v1/generate-scenario-draft', async (route) => {
    const cors = {
      'access-control-allow-origin': '*',
      'access-control-allow-headers': '*',
      'access-control-allow-methods': 'POST, OPTIONS',
    };
    if (route.request().method() === 'OPTIONS') return route.fulfill({ status: 200, headers: cors, body: 'ok' });
    return route.fulfill({
      status: 422,
      headers: { ...cors, 'content-type': 'application/json' },
      body: JSON.stringify({ error: 'draft_rejected', reasons: ['forbidden_promise'] }),
    });
  });
}

/** Мастер новой симуляции с нуля: шаги 1–4 заполнены, переход на /draft. */
async function createSimulationToDraft(page: Page, name: string) {
  const f = (label: string, value: string) => page.getByLabel(label, { exact: false }).first().fill(value);
  await page.goto('/simulations/new?start=scratch');
  await page.getByLabel('שם הסימולציה').fill(name);
  await f('שם התפקיד', 'נציג מכירות');
  await f('תחום הפעילות', 'ביטוח רכב');
  await f('המוצר או השירות', 'פוליסת ביטוח רכב מקיף');
  await f('קהל היעד', 'נהגים פרטיים בגילאי 30-50');
  await page.getByLabel('סוג הלקוח').selectOption('warm_lead');
  await f('מטרת השיחה', 'לקבוע פגישת המשך עם הלקוח');
  await f('התוצאה הרצויה', 'הלקוח מסכים לפגישת המשך');
  await page.getByLabel('הצעד הבא הרצוי').selectOption('sales_meeting');
  await page.getByRole('button', { name: 'הבא: לקוח וחשיפה' }).click();
  await page.waitForURL(/simulations\/[0-9a-f-]{36}/);

  await f('מצב הלקוח בתחילת השיחה', 'סקפטי ועסוק');
  await f('הצורך או הבעיה', 'הפוליסה מתחדשת בעוד חודש והוא מרגיש שהוא משלם יותר מדי');
  await page.getByRole('button', { name: 'הוספת פריט מידע' }).click();
  await page.locator('#simulation-info_items-0-text').fill('ללקוח שני רכבים במשפחה');
  await page.getByRole('button', { name: 'הבא: התנגדות' }).click();
  await page.waitForURL(/step=objection/);

  await f('ההתנגדות המרכזית', 'זה יקר לי מדי כרגע');
  await f('הסיבה שמאחורי ההתנגדות', 'חושש שהכיסוי לא שווה את ההפרש');
  await f('מידע שניתן לגלות באמצעות בירור', 'לא בדק את הנחת נהג צעיר');
  await f('התנאים שבהם ההתנגדות מתרככת', 'השוואה ברורה של כיסויים');
  await f('התנאים שבהם הלקוח יסרב להמשיך', 'לחץ לסגור מיד');
  await page.getByRole('button', { name: 'הבא: גבולות ההצעה' }).click();
  await page.waitForURL(/step=offer/);

  await f('מידע שהמוכר רשאי למסור', 'כיסויים, השתתפות עצמית');
  await f('מידע שהמוכר חייב למסור', 'תקופת הביטוח ותנאי ביטול');
  await f('יתרונות רלוונטיים', 'רכב חלופי');
  await f('הבטחות או ניסוחים אסורים', 'אסור להבטיח שהמחיר לא יעלה לעולם');
  await f('מידע שאסור להמציא', 'אסור להמציא הנחות');
  await page.getByRole('button', { name: 'לסקירת הטיוטה' }).click();
  await page.waitForURL(/\/draft/);
}

/** Поля ручного черновика (разделы 01–05). «מידע גלוי/נסתר» не трогаем — их уровни берутся из источника. */
const MANUAL_FIELDS: [string, string][] = [
  ['דמות הלקוח', 'QA-AUTO: דני, 40, נהג זהיר, סקפטי כלפי מכירות'],
  ['הנחיות ל-AI לשמירה על הדמות', 'להישאר בדמות, לענות בקצרה'],
  ['מצב הפתיחה', 'עונה בחוסר סבלנות: יש לך דקה'],
  ['תגובות אפשריות', 'זה יקר לי מדי כרגע'],
  ['תנאים להתקדמות', 'הנציג מציג השוואת כיסויים'],
  ['תנאים לסיום', 'הנציג לוחץ לסגור מיד'],
  ['הצעד המרבי שהלקוח מוכן לבצע', 'הסכמה לפגישת המשך'],
];

/** Видимые уведомления (alert/status) с текстом. */
async function visibleNotices(page: Page) {
  return page.evaluate(() =>
    [...document.querySelectorAll('[role=alert],[role=status]')]
      .filter((e) => (e as HTMLElement).offsetParent && (e as HTMLElement).innerText.trim())
      .map((e) => (e as HTMLElement).innerText.replace(/\s+/g, ' ').trim()),
  );
}

const VIEWPORTS = [
  { label: '1440', viewport: { width: 1440, height: 900 } },
  { label: '375', viewport: { width: 375, height: 812 } },
];

test.describe('Черновик сценария — уведомления после ручного сохранения (#1f2eaae83231d71a353ee5d2)', () => {
  for (const { label, viewport } of VIEWPORTS) {
    test(`сбой генерации → ручной черновик → сохранение: только «הטיוטה נשמרה», без алерта сбоя, ширина ${label} @desktop @data #1f2eaae83231d71a353ee5d2`, async ({ asUser }) => {
      test.setTimeout(120_000);
      const page = await asUser('business');
      await page.setViewportSize(viewport);
      const name = `QA-AUTO-DRAFT-${label}-${runStamp()}`;
      test.info().annotations.push({ type: 'test-data', description: `симуляция «${name}» (טיוטה), не удаляется` });

      await failGeneration(page);
      await createSimulationToDraft(page, name);

      // Генерация запускается сама или кнопкой «הפקת טיוטת תרחיש»; ответ подменён на 422.
      const failAlert = page.getByText(FAIL_TITLE, { exact: true });
      const generate = page.getByRole('button', { name: 'הפקת טיוטת תרחיש' });
      await expect(failAlert.or(generate).first()).toBeVisible({ timeout: 30_000 });
      if (await generate.isVisible()) await generate.click();
      await expect(failAlert).toBeVisible();
      await expect(page.getByRole('button', { name: 'ניסיון נוסף' })).toBeVisible();

      // Ручной черновик: заполнить пустые разделы и сохранить как новую версию.
      await page.getByRole('button', { name: 'כתיבת טיוטה ידנית' }).click();
      const form = page.getByRole('form', { name: 'עריכת הטיוטה' });
      await expect(form).toBeVisible();
      for (const [field, value] of MANUAL_FIELDS) {
        const box = form.getByRole('textbox', { name: field, exact: true });
        if ((await box.count()) && !(await box.inputValue()).trim()) await box.fill(value);
      }
      const saved = page.waitForResponse((r) => r.url().includes('save_scenario_draft'));
      await form.getByRole('button', { name: 'שמירה כגרסה חדשה' }).click();
      expect((await saved).ok(), 'save_scenario_draft должен пройти').toBeTruthy();

      // Источник: «מה רצוי» — «אחרי שמירה מוצלחת מוצג רק מצב ההצלחה»; AC — алерт сбоя не показывается.
      await expect(page.getByText(SAVED_TITLE, { exact: true })).toBeVisible();
      await expect(failAlert).toHaveCount(0);
      const notices = await visibleNotices(page);
      expect(notices.filter((n) => n.includes('נכשל')), `видимые уведомления: ${JSON.stringify(notices)}`).toEqual([]);
      expect(notices.filter((n) => n.includes(SAVED_TITLE))).toHaveLength(1);
    });
  }
});
